package com.avizero.avidrive.api;

import com.avizero.avidrive.domain.*; import com.avizero.avidrive.repository.*; import com.avizero.avidrive.security.AuthUser;
import jakarta.transaction.Transactional; import java.io.*; import java.nio.file.*; import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/uploads") public class UploadController {
 private final UploadRepository uploads; private final UploadChunkRepository chunks; private final StoredFileRepository files; private final FolderRepository folders; private final UserRepository users; private final SettingRepository settings; private final Path root=Paths.get("storage/tmp/uploads");
 public UploadController(UploadRepository u,UploadChunkRepository c,StoredFileRepository f,FolderRepository d,UserRepository users,SettingRepository s){uploads=u;chunks=c;files=f;folders=d;this.users=users;settings=s;}
 @PostMapping("/init") public ResponseEntity<?> init(@RequestBody InitRequest r,Authentication a){Long owner=id(a);if(r.file_name()==null||r.file_name().isBlank()||r.total_size()==null||r.total_size()<0||r.chunk_size()==null||r.chunk_size()<=0)return error(400,"Некорректные параметры загрузки");if(r.chunk_size()>8*1024*1024+65536)return error(400,"Размер чанка превышает 8 МБ");if(r.target_folder_id()!=null&&!ownedFolder(r.target_folder_id(),owner))return error(404,"Папка не найдена");String mode=r.conflict_mode()==null?"ASK":r.conflict_mode();if(!Set.of("REPLACE","KEEP_BOTH","ASK").contains(mode))return error(400,"Некорректный conflict_mode");if(files.existsByOwnerIdAndFolderIdAndName(owner,r.target_folder_id(),r.file_name())&&"ASK".equals(mode))return error(409,"Файл уже существует");if(!quotaAvailable(owner,r.total_size()))return error(413,"Недостаточно квоты");try{Files.createDirectories(root);Upload u=new Upload();u.sessionUuid=UUID.randomUUID().toString();u.ownerId=owner;u.fileName=r.file_name();u.relativePath=r.relative_path();u.targetFolderId=r.target_folder_id();u.totalSize=r.total_size();u.chunkSize=r.chunk_size();u.conflictMode=mode;u.status="PAUSED";u.expiresAt=Instant.now().plus(24,java.time.temporal.ChronoUnit.HOURS).toString();uploads.save(u);return ResponseEntity.ok(Map.of("session_uuid",u.sessionUuid));}catch(IOException e){return error(500,"Не удалось создать сессию");}}
 @PostMapping("/{uuid}/chunks/{index}") @Transactional public ResponseEntity<?> chunk(@PathVariable String uuid,@PathVariable int index,@RequestBody byte[] body,Authentication a){Upload u=owned(uuid,id(a));if(u==null||!Set.of("PAUSED","UPLOADING").contains(u.status))return error(400,"Сессия недействительна");if(body.length>8*1024*1024+65536||index<0)return error(400,"Некорректный чанк");long offset=(long)index*u.chunkSize;if(offset+body.length>u.totalSize)return error(400,"Чанк превышает размер файла");if(!quotaAvailable(u.ownerId,body.length-uChunk(u,index)))return error(413,"Недостаточно квоты");try{Path dir=root.resolve(uuid).normalize();if(!dir.startsWith(root))return error(400,"Недопустимый путь");Files.createDirectories(dir);Path path=dir.resolve(index+".part");Files.write(path,body);UploadChunkId cid=new UploadChunkId();cid.uploadId=u.id;cid.chunkIndex=index;UploadChunk c=new UploadChunk();c.id=cid;c.sizeBytes=(long)body.length;c.storagePath=path.toString();chunks.save(c);u.receivedBytes=chunks.findByIdUploadIdOrderByIdChunkIndex(u.id).stream().mapToLong(x->x.sizeBytes).sum();u.status="UPLOADING";uploads.save(u);return ResponseEntity.ok(Map.of("received_bytes",u.receivedBytes));}catch(IOException e){return error(500,"Не удалось сохранить чанк");}}
 @PostMapping("/{uuid}/complete") @Transactional public ResponseEntity<?> complete(@PathVariable String uuid,Authentication a){Upload u=owned(uuid,id(a));if(u==null)return error(404,"Сессия не найдена");List<UploadChunk> cs=chunks.findByIdUploadIdOrderByIdChunkIndex(u.id);if(u.receivedBytes==null||u.receivedBytes!=u.totalSize||cs.isEmpty())return error(400,"Размер или набор чанков не совпадает");try{Long folder=u.targetFolderId;String name=uniqueName(u.ownerId,folder,u.fileName,u.conflictMode);StoredFile old=files.findByOwnerIdAndFolderIdAndName(u.ownerId,folder,u.fileName).orElse(null);if(old!=null&&"REPLACE".equals(u.conflictMode))files.delete(old);Path destination=Paths.get("storage/files",String.valueOf(u.ownerId));Files.createDirectories(destination);Path output=destination.resolve(UUID.randomUUID()+"-"+name).normalize();if(!output.startsWith(destination))return error(400,"Недопустимый путь");try(OutputStream out=Files.newOutputStream(output)){for(UploadChunk c:cs)Files.copy(Paths.get(c.storagePath),out);}StoredFile f=new StoredFile();f.ownerId=u.ownerId;f.folderId=folder;f.name=name;f.sizeBytes=u.totalSize;f.storagePath=output.toString();f.mimeType=java.nio.file.Files.probeContentType(Paths.get(name));files.save(f);u.status="COMPLETED";uploads.save(u);deleteTemp(uuid);return ResponseEntity.ok(Map.of("file_id",f.id));}catch(IOException e){return error(500,"Не удалось завершить загрузку");}}
 @PostMapping("/{uuid}/cancel") @Transactional public ResponseEntity<?> cancel(@PathVariable String uuid,Authentication a){Upload u=owned(uuid,id(a));if(u==null)return error(404,"Сессия не найдена");u.status="CANCELLED";uploads.save(u);deleteTemp(uuid);return ResponseEntity.noContent().build();}
 @GetMapping("/active") public List<?> active(Authentication a){return uploads.findByOwnerIdAndStatusIn(id(a),List.of("PAUSED","UPLOADING")).stream().map(u->Map.of("session_uuid",u.sessionUuid,"file_name",u.fileName,"total_size",u.totalSize,"received_bytes",u.receivedBytes,"status",u.status)).toList();}
 @Scheduled(cron="0 0 * * * *") @Transactional public void expire(){uploads.findAll().stream().filter(u->Set.of("PAUSED","UPLOADING").contains(u.status)&&u.expiresAt!=null&&Instant.parse(u.expiresAt).isBefore(Instant.now())).forEach(u->{u.status="EXPIRED";uploads.save(u);deleteTemp(u.sessionUuid);});}
 private long uChunk(Upload u,int i){UploadChunkId key=new UploadChunkId();key.uploadId=u.id;key.chunkIndex=i;return chunks.findById(key).map(x->x.sizeBytes).orElse(0L);} private Upload owned(String uuid,Long owner){return uploads.findBySessionUuid(uuid).filter(x->x.ownerId.equals(owner)).orElse(null);} private Long id(Authentication a){return ((AuthUser)a.getPrincipal()).id();} private boolean ownedFolder(Long id,Long owner){return folders.findById(id).filter(x->x.ownerId.equals(owner)).isPresent();} private boolean quotaAvailable(Long owner,long extra){var u=users.findById(owner).orElseThrow();if(u.quotaMb!=null&&u.quotaMb>0&&u.usedBytes+extra>u.quotaMb*1024*1024)return false;var s=settings.findById(1L).orElseThrow();return s.globalQuotaMb==null||s.globalQuotaMb==0||globalUsed()+extra<=s.globalQuotaMb*1024*1024;} private long globalUsed(){return users.findAll().stream().mapToLong(x->x.usedBytes==null?0:x.usedBytes).sum();} private String uniqueName(Long o,Long f,String n,String mode){if(!"KEEP_BOTH".equals(mode)||!files.existsByOwnerIdAndFolderIdAndName(o,f,n))return n;int dot=n.lastIndexOf('.');String base=dot>0?n.substring(0,dot):n,ext=dot>0?n.substring(dot):"";int i=1;while(files.existsByOwnerIdAndFolderIdAndName(o,f,base+" ("+i+")"+ext))i++;return base+" ("+i+")"+ext;} private void deleteTemp(String uuid){try{Path p=root.resolve(uuid);if(Files.exists(p))Files.walk(p).sorted(Comparator.reverseOrder()).forEach(x->{try{Files.deleteIfExists(x);}catch(IOException ignored){}});}catch(IOException ignored){}} private ResponseEntity<Map<String,String>> error(int s,String m){return ResponseEntity.status(s).body(Map.of("message",m));}
 public record InitRequest(String file_name,String relative_path,Long target_folder_id,Long total_size,Long chunk_size,String conflict_mode){}
}


